import random
from itertools import combinations

def bfs_girth_check(adj, u, v, min_girth):
    # if adding edge u-v would create cycle of length < min_girth
    # BFS from u, check if v reachable in <= min_girth - 2 steps (without using edge u-v)
    # Actually simpler: compute distance from u to v in current graph; if < min_girth-1, adding creates cycle < min_girth
    from collections import deque
    dist = {u: 0}
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= min_girth - 2:
            continue
        for y in adj[x]:
            if y not in dist:
                dist[y] = dist[x] + 1
                q.append(y)
    return v not in dist or dist[v] >= min_girth - 1

def try_build(n, min_deg, max_deg, min_girth, seed):
    random.seed(seed)
    adj = {i:set() for i in range(n)}
    deg = [0]*n
    # random order
    pairs = list(combinations(range(n),2))
    random.shuffle(pairs)
    for u,v in pairs:
        if deg[u]>=max_deg or deg[v]>=max_deg: continue
        if bfs_girth_check(adj,u,v,min_girth):
            adj[u].add(v); adj[v].add(u)
            deg[u]+=1; deg[v]+=1
    if all(min_deg<=deg[i]<=max_deg for i in range(n)):
        return adj
    return None

