# Strategy: greedy with repair. Try to make all degrees >= 3.
def build(n, min_deg, max_deg, min_girth, seed, iters=5000):
    random.seed(seed)
    adj = {i:set() for i in range(n)}
    deg = [0]*n
    # prioritize low-degree vertices
    for _ in range(iters):
        # find vertex with lowest degree
        lows = [i for i in range(n) if deg[i]<min_deg]
        if not lows:
            break
        u = random.choice(lows)
        # candidates: vertices v != u, not neighbor, deg[v]<max_deg, girth ok
        cands = [v for v in range(n) if v!=u and v not in adj[u] and deg[v]<max_deg]
        random.shuffle(cands)
        # prefer candidates also low deg
        cands.sort(key=lambda v: deg[v])
        added = False
        for v in cands:
            if bfs_girth_check(adj,u,v,min_girth):
                adj[u].add(v); adj[v].add(u)
                deg[u]+=1; deg[v]+=1
                added=True
                break
        if not added:
            # need to break out; try removing a random edge and continue
            # pick a random edge to remove
            all_edges = [(a,b) for a in range(n) for b in adj[a] if a<b]
            if not all_edges: break
            a,b = random.choice(all_edges)
            adj[a].discard(b); adj[b].discard(a)
            deg[a]-=1; deg[b]-=1
    if all(min_deg<=deg[i]<=max_deg for i in range(n)):
        return adj
    return None

for s in range(2000):
    r = build(26,3,5,7,s)
    if r:
        edges=[(u,v) for u in range(26) for v in r[u] if u<v]
        degs=[len(r[i]) for i in range(26)]
        g = compute_girth(r,26)
        if g>=7 and min(degs)>=3 and max(degs)<=5:
            print("seed",s,"edges",len(edges),"deg",min(degs),max(degs),"girth",g)
            print(edges)
